/** SPARQL generated from the filters: repository-wide value counts and the "visual query" of the current selection. */
import type { EndpointFacetValue, SparqlResponse } from "./explorer-types.ts";
import {
  DATE_LEXICAL,
  NUMBER_LEXICAL,
  formatRangeDay,
  parseRangeValue,
  rangeDaySparql,
  rangeLexicalSparql,
} from "./facet-ranges.ts";
import { TYPE_FACET_ID } from "./graph-facets.ts";
import { intrinsicFacetSparqlFilter } from "./graph-filters.ts";
import { compactTerm, isSafeSparqlIri } from "./graph-terms.ts";
import { UNTYPED_IRI_TYPE } from "./graph-visuals.ts";
import { sparqlFacetValueToken, sparqlNodeId } from "./rdf-terms.ts";
import { iriToken, scoped, type GraphScope } from "./rdf-vocabulary.ts";
import { QueryFailure } from "./request-batching.ts";

const COUNT_SOURCE_BATCH_SIZE = 120;

function countLabelLanguage(languages: readonly string[]) {
  return languages.find((tag) => /^[A-Za-z]{1,8}(-[A-Za-z0-9]{1,8})*$/.test(tag) && tag !== "und") ?? "en";
}

/** How many of the sources have each value of the predicate in the repository, with the values' labels. */
export function facetCountQuery(
  sourceIds: readonly string[],
  predicate: string,
  scope: GraphScope = "default",
  languages: readonly string[] = ["en"],
) {
  const values = [...new Set(sourceIds.filter(isSafeSparqlIri))]
    .map(iriToken)
    .join(" ");
  const relation =
    predicate === TYPE_FACET_ID
      ? "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>"
      : iriToken(predicate);
  const language = countLabelLanguage(languages);
  return `PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?value ?valueLabel ?count WHERE {
  { SELECT ?value (COUNT(DISTINCT ?source) AS ?count) WHERE {
    VALUES ?source { ${values} }
    ${scoped(`?source ${relation} ?value .`, scope)}
  } GROUP BY ?value }
  OPTIONAL {
    ${scoped("?value rdfs:label ?valueLabel .", scope)}
    FILTER(LANG(?valueLabel) = "" || LANGMATCHES(LANG(?valueLabel), "${language}"))
  }
}
ORDER BY DESC(?count)`;
}

/** Count every distinct source in bounded requests, then choose labels and the top 100 over the whole histogram. */
export async function countFacetValues(
  sourceIds: readonly string[],
  predicate: string,
  scope: GraphScope,
  languages: readonly string[],
  execute: (query: string, signal?: AbortSignal) => Promise<SparqlResponse>,
  options: { signal?: AbortSignal; isCurrent?: () => boolean } = {},
): Promise<EndpointFacetValue[] | null> {
  const sources = [...new Set(sourceIds.filter(isSafeSparqlIri))];
  const current = () => !options.signal?.aborted && (options.isCurrent?.() ?? true);
  const language = countLabelLanguage(languages).toLocaleLowerCase();
  type Count = { id: string; count: number; fallback: string; labels: Map<string, number> };
  const totals = new Map<string, Count>();
  for (let offset = 0; offset < sources.length; offset += COUNT_SOURCE_BATCH_SIZE) {
    const pending = [sources.slice(offset, offset + COUNT_SOURCE_BATCH_SIZE)];
    while (pending.length) {
      if (!current()) {
        return null;
      }
      const batchSources = pending.pop()!;
      const query = facetCountQuery(batchSources, predicate, scope, languages);
      let response: SparqlResponse;
      try {
        response = await execute(query, options.signal);
      } catch (error) {
        if (!(error instanceof QueryFailure) || error.status !== 413) {
          throw error;
        }
        if (!current()) {
          return null;
        }
        if (batchSources.length === 1) {
          throw error;
        }
        // HTTP 413 rejects the request size. Smaller disjoint source batches make progress without guessing
        // the server's configured character/byte limit or counting any failed attempt's sources twice.
        const middle = Math.ceil(batchSources.length / 2);
        pending.push(batchSources.slice(middle), batchSources.slice(0, middle));
        continue;
      }
      if (!current()) {
        return null;
      }
      const batch = new Map<string, Count>();
      for (const row of response.results?.bindings ?? []) {
        const value = row.value;
        const count = Number(row.count?.value);
        if (!value || !Number.isFinite(count) || count < 0) {
          continue;
        }
        const id = sparqlNodeId(value);
        let entry = batch.get(id);
        if (!entry) {
          entry = { id, count, fallback: compactTerm(value.value, 38), labels: new Map() };
          batch.set(id, entry);
        }
        // OPTIONAL labels repeat the same aggregate count; they never represent additional sources.
        const label = row.valueLabel;
        if (label?.value) {
          const tag = label["xml:lang"]?.toLocaleLowerCase() ?? "";
          const rank = tag === language ? 0 : tag.startsWith(`${language}-`) ? 1 : tag ? 3 : 2;
          entry.labels.set(label.value, Math.min(entry.labels.get(label.value) ?? Infinity, rank));
        }
      }
      for (const [id, value] of batch) {
        let total = totals.get(id);
        if (!total) {
          total = { ...value, count: 0, labels: new Map() };
          totals.set(id, total);
        }
        total.count += value.count;
        for (const [label, rank] of value.labels) {
          total.labels.set(label, Math.min(total.labels.get(label) ?? Infinity, rank));
        }
      }
    }
  }
  if (!current()) {
    return null;
  }
  return [...totals.values()]
    .map(({ id, count, fallback, labels }) => ({
      id,
      count,
      label: [...labels]
        .sort(([left, leftRank], [right, rightRank]) => leftRank - rightRank || left.localeCompare(right))[0]?.[0]
        ?? fallback,
    }))
    .sort((left, right) =>
      right.count - left.count || left.label.localeCompare(right.label) || left.id.localeCompare(right.id))
    .slice(0, 100);
}

export type QueryRange = { kind: "number" | "date"; from: string; to: string };

/** A range filter as SPARQL: numbers compare numerically, dates by their ISO day (so date and dateTime both work). */
export function rangeSparqlFilter(variable: string, range: QueryRange) {
  const from = range.from.trim();
  const to = range.to.trim();
  if (!from && !to) {
    return null;
  }
  const text = rangeLexicalSparql(variable);
  const value = range.kind === "number" ? `<http://www.w3.org/2001/XMLSchema#double>(${text})` : rangeDaySparql(text);
  const conditions = [
    `isLiteral(${variable})`,
    `REGEX(${text}, "^${range.kind === "number" ? NUMBER_LEXICAL : DATE_LEXICAL}$")`,
    range.kind === "number" ? `ABS(${value}) <= 1.7976931348623157e308` : `${value} = ${value}`,
  ];
  for (const [bound, operator] of [[from, ">="], [to, "<="]] as const) {
    const parsed = parseRangeValue(range.kind, bound);
    if (!Number.isFinite(parsed)) {
      continue;
    }
    const token = range.kind === "number"
      ? `"${parsed}"^^<http://www.w3.org/2001/XMLSchema#double>`
      : `"${formatRangeDay(parsed)}"^^<http://www.w3.org/2001/XMLSchema#date>`;
    conditions.push(`${value} ${operator} ${token}`);
  }
  return `FILTER(${conditions.join(" && ")})`;
}

export function formatRangeValue(kind: "number" | "date", value: number) {
  if (kind === "date") {
    return formatRangeDay(value);
  }
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(6)));
}

export function generatedFacetQuery(
  selectedFacetValues: Map<string, Set<string>>,
  options: { wikidata: boolean; ranges?: ReadonlyMap<string, QueryRange> },
) {
  const activeFacets = [...selectedFacetValues.entries()].filter(
    ([, values]) => values.size > 0,
  );
  const lines: string[] = [];
  let index = 0;
  activeFacets.forEach(([facetId, values]) => {
    const intrinsicFilter = intrinsicFacetSparqlFilter(
      facetId,
      values,
    );
    if (intrinsicFilter) {
      lines.push(`  ${intrinsicFilter}`);
      return;
    }
    const relation =
      facetId === TYPE_FACET_ID
        ? options.wikidata
          ? "<http://www.wikidata.org/prop/direct/P31>"
          : "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>"
        : iriToken(facetId);
    if (facetId === TYPE_FACET_ID) {
      const untypedSelected = values.has(UNTYPED_IRI_TYPE.id);
      const typedTokens = [...values]
        .filter((value) => value !== UNTYPED_IRI_TYPE.id)
        .map(sparqlFacetValueToken)
        .filter((value): value is string => Boolean(value));
      const typedVariable = `?facetTypeValue${index}`;
      const typedMatch = typedTokens.length
        ? `EXISTS { ?focus ${relation} ${typedVariable} . VALUES ${typedVariable} { ${typedTokens.join(" ")} } }`
        : "false";
      const untypedMatch = untypedSelected
        ? `isIRI(?focus) && NOT EXISTS { ?focus ${relation} ?anyType }`
        : "false";
      lines.push(`  FILTER(${untypedMatch} || ${typedMatch})`);
      index += 1;
      return;
    }
    const variable = `?facetValue${index}`;
    lines.push(`  ?focus ${relation} ${variable} .`);
    const range = options.ranges?.get(facetId);
    const rangeFilter = range ? rangeSparqlFilter(variable, range) : null;
    if (rangeFilter) {
      lines.push(`  ${rangeFilter}`);
      index += 1;
      return;
    }
    const tokens = [...values]
      .map(sparqlFacetValueToken)
      .filter((value): value is string => Boolean(value));
    if (!tokens.length) {
      lines.push("  FILTER(false)");
      index += 1;
      return;
    }
    lines.push(
      `  VALUES ${variable} { ${tokens.join(" ")} }`,
    );
    index += 1;
  });
  if (!activeFacets.length) {
    return "SELECT ?source ?predicate ?target WHERE {\n  ?source ?predicate ?target .\n}\nLIMIT 300";
  }
  // BIND cannot read a variable supplied only by a join outside its UNION branch. Each branch binds its own
  // statement first, then applies every facet to the same endpoint, preserving OR within and AND across facets.
  const branch = (endpoint: "source" | "target") => [
    "  {",
    "    ?source ?predicate ?target .",
    `    BIND(?${endpoint} AS ?focus)`,
    ...lines.map((line) => `  ${line}`),
    "  }",
  ].join("\n");
  return [
    "SELECT DISTINCT ?source ?predicate ?target WHERE {",
    branch("source"),
    "  UNION",
    branch("target"),
    "}",
    "LIMIT 300",
  ].join("\n");
}
